//! Compiles the parser generated by Tree-sitter (`grammar/src/parser.c`), gives its highlighting
//! query to the crate (`highlights.scm` in `OUT_DIR`), and the commit the compiler is built from
//! (`CADASTRE_COMMIT`), so that the WebAssembly module of a playground can be told from another build.
//!
//! The grammar is read in place in a clone of the repository, from `vendor/` in a package of
//! crates.io, where `compiler/vendor.sh` copies it.

use std::path::{Path, PathBuf};

/// The root of the repository, when built from a clone.
fn repository() -> Option<PathBuf> {
    let root: PathBuf = [env!("CARGO_MANIFEST_DIR"), "..", "..", ".."].iter().collect();
    root.join("grammar").join("grammar.js").is_file().then_some(root)
}

/// A file of the repository, by its path from the root: in place, or copied into `vendor/`.
fn repository_file(path: &str) -> PathBuf {
    match repository() {
        Some(root) => root.join(path),
        None => Path::new(env!("CARGO_MANIFEST_DIR")).join("vendor").join(path),
    }
}

fn main() {
    let src = repository_file("grammar/src");
    let parser = src.join("parser.c");

    let mut build = cc::Build::new();
    build.include(&src).file(&parser).warnings(false);

    // wasm32-unknown-unknown has no libc: the tree-sitter-language crate provides
    // minimal headers, and the tree-sitter runtime provides the allocator.
    if std::env::var("TARGET").unwrap_or_default().starts_with("wasm32-unknown") {
        let headers = std::env::var("DEP_TREE_SITTER_LANGUAGE_WASM_HEADERS")
            .expect("tree-sitter-language exposes its wasm headers for this target");
        build.include(headers);
    }

    build.compile("tree-sitter-cadastre");

    println!("cargo:rerun-if-changed={}", parser.display());

    let highlights = repository_file("grammar/queries/highlights.scm");
    let out = PathBuf::from(std::env::var("OUT_DIR").expect("set by cargo"));
    std::fs::copy(&highlights, out.join("highlights.scm")).expect("the highlighting query of the grammar");
    println!("cargo:rerun-if-changed={}", highlights.display());

    // The commit, when built from a clone: `unknown` otherwise (a package of crates.io).
    let Some(root) = repository() else {
        println!("cargo:rustc-env=CADASTRE_COMMIT=unknown");
        return;
    };
    let commit = std::process::Command::new("git")
        .args(["rev-parse", "--short=7", "HEAD"])
        .current_dir(&root)
        .output()
        .ok()
        .filter(|o| o.status.success())
        .map(|o| String::from_utf8_lossy(&o.stdout).trim().to_owned())
        .filter(|c| !c.is_empty())
        .unwrap_or_else(|| "unknown".to_owned());
    println!("cargo:rustc-env=CADASTRE_COMMIT={commit}");
    let git = root.join(".git");
    if git.is_dir() {
        println!("cargo:rerun-if-changed={}", git.join("HEAD").display());
        if let Ok(head) = std::fs::read_to_string(git.join("HEAD"))
            && let Some(reference) = head.trim().strip_prefix("ref: ")
        {
            println!("cargo:rerun-if-changed={}", git.join(reference).display());
        }
        println!("cargo:rerun-if-changed={}", git.join("packed-refs").display());
    }
}
